import json,csv,hashlib,html,sys
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

def run(root):
 root=Path(root);records=json.loads((root/'results.json').read_text());good=[x for x in records if x['status']=='completed'];ref=list(csv.DictReader((root/'kinfitr_graphical.csv').open()));reg=json.loads((root/'registration_review'/'registrations.json').read_text())
 summary=dict(protocol_id='PETKIN-PS13-EXTERNAL-2026-11-03-A',scans_expected=20,scans_completed=len(good),failures=[x for x in records if x['status']!='completed'],subjects=len(set(x['subject'] for x in good)),cohort_role='Independent tracer/people, now exposed for future studies',research_released=sum(x['full_research_fit']['research_screen']['passed'] for x in good),local_qc_passed=sum(x['full_research_fit']['local_qc_passed'] for x in good),closed_profiles=sum(bool(x['full_research_fit']['macro_profile'] and x['full_research_fit']['macro_profile']['closed']) for x in good),structured_residuals=sum('structured_residuals_require_review' in x['full_research_fit']['research_screen']['reasons'] for x in good),measured_registration_pairs_completed=sum(x['status']=='completed' for x in reg),registration_accuracy_status='Unmeasured: independent references absent',EXT_01='Not passed: input certification, anatomical ROI verification and independent review absent',REG_02='Blocked: no independent measured-human reference transforms or landmarks')
 for mode in ('fixed_delay','fitted_delay'):
  values=[x['cross_validation'][mode]['held_frame_nrmse'] for x in good];summary[mode]=dict(median_nrmse=float(np.median(values)),q95_nrmse=float(np.quantile(values,.95)),maximum_nrmse=float(np.max(values)),n=len(values),exploratory_prediction_targets_met=bool(np.median(values)<=.1 and np.quantile(values,.95)<=.2))
 comparisons=[]
 for x in good:
  rr=next(v for v in ref if v['scan']==x['scan'] and v['tstar']=='30')
  for method in ('logan','ma1'):
   own=x['graphical'][method][1]['raw_VT'];other=float(rr[method+'_VT']);comparisons.append(dict(scan=x['scan'],method=method,petkin_raw_VT=own,kinfitr_VT=other,absolute_relative_difference=abs(own-other)/abs(other),status=rr['status']))
 summary['reference_comparison']={m:dict(n=sum(x['method']==m for x in comparisons),median_absolute_relative_difference=float(np.median([x['absolute_relative_difference'] for x in comparisons if x['method']==m])),maximum_absolute_relative_difference=float(max(x['absolute_relative_difference'] for x in comparisons if x['method']==m))) for m in ('logan','ma1')}
 pairs=[]
 for subject in sorted(set(x['subject'] for x in good)):
  ss=[x for x in good if x['subject']==subject];a=next((x for x in ss if x['session']=='ses-baseline'),None);b=next((x for x in ss if x['session']=='ses-rescan'),None)
  if a and b:
   av,bv=a['full_research_fit']['raw_VT'],b['full_research_fit']['raw_VT'];pairs.append(dict(subject=subject,baseline_raw_VT=av,rescan_raw_VT=bv,symmetric_absolute_difference=2*abs(av-bv)/(av+bv),both_local_qc_passed=a['full_research_fit']['local_qc_passed'] and b['full_research_fit']['local_qc_passed'],released=False))
 summary['test_retest']=dict(n_subjects=len(pairs),pairs=pairs,interpretation='Descriptive raw withheld estimates from separate uptake masks, uncorrected motion, and uncertain calibration; not validated reproducibility')
 (root/'summary.json').write_text(json.dumps(summary,indent=2));(root/'reference_comparison.json').write_text(json.dumps(comparisons,indent=2))
 fig,axes=plt.subplots(5,4,figsize=(16,18))
 for ax,x in zip(axes.flat,good):
  tac=np.genfromtxt(root/(x['scan']+'_tac.csv'),names=True,delimiter=',');time=(tac['start']+tac['end'])/2;held=tac['held'].astype(bool)
  ax.plot(time,tac['activity'],'.',color='#263d50');ax.plot(time,x['cross_validation']['fixed_delay']['prediction'],color='#008d93',lw=1,label='Train fit');ax.scatter(time[held],tac['activity'][held],facecolors='none',edgecolors='#cc542b',s=30,label='Held frame');ax.set_title(x['scan']+'\nNRMSE '+format(x['cross_validation']['fixed_delay']['held_frame_nrmse'],'.1%'),fontsize=9);ax.set_xlabel('Minutes');ax.set_ylabel('Bq/mL')
 axes.flat[0].legend(fontsize=7);fig.suptitle('Independent PS13 cohort: frozen fixed-delay model, all 20 scans\nPrediction checks; true kinetic parameters unknown',fontsize=15);fig.tight_layout(rect=[0,0,1,.96]);fig.savefig(root/'held_frame_predictions.png',dpi=140);plt.close(fig)
 fixed=summary['fixed_delay'];fitted=summary['fitted_delay'];rows=[]
 for x in good:rows.append(f"<tr><td>{x['scan']}</td><td>{x['cross_validation']['fixed_delay']['held_frame_nrmse']:.2%}</td><td>{x['cross_validation']['fitted_delay']['held_frame_nrmse']:.2%}</td><td>{'pass' if x['full_research_fit']['local_qc_passed'] else 'review'}</td><td>{html.escape(', '.join(x['full_research_fit']['research_screen']['reasons']))}</td></tr>")
 body=f'''<h1>Independent PS13 evaluation</h1><p><strong>20 scans / 10 people. Full research validation remains incomplete.</strong></p><p>The frozen model predicted held-out time points with median normalized error {fixed['median_nrmse']:.2%}, 95th percentile {fixed['q95_nrmse']:.2%}, and worst case {fixed['maximum_nrmse']:.2%}. With fitted delay, the secondary model achieved {fitted['median_nrmse']:.2%} median error; this was not used to select or replace the primary result.</p><p>Both exploratory prediction targets were met, but only {summary['local_qc_passed']}/20 full fits passed local QC and {summary['closed_profiles']}/20 had closed macroparameter profiles. {summary['structured_residuals']}/20 showed structured residuals. All 20 estimates remain withheld by the unchanged research screen.</p><p>These are prediction errors, not errors against known kinetic parameters. Uptake masks are exploratory and are not anatomical brain regions. No motion correction was applied in this kinetic-only experiment. Independent calibration, blood decay convention, input timing, vascular assumptions, anatomy, and expert review remain unresolved.</p><h2>Independent software comparison</h2><p>Unmodified pinned kinfitr Logan and MA1 functions were run on the same extracted curves. Agreement assesses calculation consistency, not biological accuracy. Source-method input and frame integration conventions differ.</p><pre>{html.escape(json.dumps(summary['reference_comparison'],indent=2))}</pre><h2>All held-frame predictions</h2><img src="held_frame_predictions.png" style="width:100%"><h2>Every scan retained</h2><table><thead><tr><th>Scan</th><th>Primary error</th><th>Secondary error</th><th>Local QC</th><th>Research screen</th></tr></thead><tbody>{''.join(rows)}</tbody></table><h2>Measured PET–MRI</h2><p>{summary['measured_registration_pairs_completed']}/20 automatic registrations completed. No independent landmark errors have been measured. An attractive overlay or registration metric does not establish accuracy.</p><p><a href="registration_review/index.html">Open automatic alignment review pack</a>. Expert landmark placement must use native images independently of these overlays.</p><h2>Test–retest warning</h2><p>None of the four repeat-scan pairs passed local QC on both scans. Raw withheld VT estimates show substantial variation, including a near-boundary, non-identifiable estimate above 20,000 mL/mL. These results do not establish reproducibility. See summary.json for every pair.</p><h2>What still prevents qualification</h2><p>EXT-01 has new external evidence but still needs source verification, anatomical ROIs and independent review. REG-02 needs independent measured-human reference landmarks/transforms and a reviewed tolerance for at least 10 pairs. RIRE states that its truth transforms remain sequestered and its former evaluation service is no longer maintained.</p><p>Sources: <a href="https://openneuro.org/datasets/ds004868/versions/1.0.4">OpenNeuro PS13</a>; <a href="https://jnm.snmjournals.org/content/jnumed/early/2024/11/14/jnumed.124.267928.full.pdf">Original PS13 study</a>; <a href="https://rire.insight-journal.org/">RIRE availability</a>.</p><p><a href="PROTOCOL.json">Frozen protocol</a> · <a href="summary.json">Machine-readable summary</a> · <a href="source_manifest.json">Source checksums</a></p>'''
 (root/'REPORT.html').write_text('<!doctype html><meta charset="utf-8"><title>Independent PS13 evaluation</title><style>body{font:16px system-ui;max-width:1150px;margin:40px auto;padding:0 20px;color:#23313e}p{line-height:1.6}table{border-collapse:collapse;font-size:13px}td,th{padding:9px;border:1px solid #ccc;text-align:left}h1,h2{color:#135b62}</style>'+body)
 regroot=root/'registration_review';index=['<!doctype html><meta charset="utf-8"><title>PET–MRI review</title><h1>Automatic alignment review — accuracy unmeasured</h1><p>These overlays are for QC only. Independent landmark raters must use the native PET and MRI images without viewing these alignments first. Slice numbers refer to the native image grid, not standardized axial planes.</p>']
 for r in reg:
  index.append(f"<h2>{r['scan']}</h2><p>Status: {r['status']}; independent truth absent.</p>")
  if r['status']=='completed':index.append(f"<img width='100%' src='{r['scan']}/overlay.png'><p><a href='{r['scan']}/pet_mean_native.nii.gz'>Native PET mean</a> · <a href='{r['scan']}/mri_4mm.nii.gz'>Native MRI</a> · <a href='{r['scan']}/mri_to_pet.tfm'>Automatic transform, LPS mm</a></p>")
 (regroot/'index.html').write_text('\n'.join(index))
 print(json.dumps(summary,indent=2))
if __name__=='__main__':run(sys.argv[1])
